CREATE TABLE "auth_personal_access_tokens" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" bigint NOT NULL,
  "name" character varying NOT NULL,
  "token_prefix" character varying NOT NULL,
  "secret_hash" character varying NOT NULL,
  "scopes" jsonb NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "revoked_at" timestamptz NULL,
  "last_used_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id"),
  CONSTRAINT "auth_personal_access_tokens_users_user_id"
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE UNIQUE INDEX "auth_personal_access_tokens_secret_hash_key"
  ON "auth_personal_access_tokens" ("secret_hash");
CREATE INDEX "auth_personal_access_tokens_user_live_created_at_idx"
  ON "auth_personal_access_tokens" ("user_id", "deleted_at", "created_at" DESC, "id" DESC);

COMMENT ON TABLE "auth_personal_access_tokens" IS '个人 API 令牌表（认证模块）';
COMMENT ON COLUMN "auth_personal_access_tokens"."id" IS '个人 API 令牌主键';
COMMENT ON COLUMN "auth_personal_access_tokens"."user_id" IS '关联用户资料的稳定标识';
COMMENT ON COLUMN "auth_personal_access_tokens"."name" IS '用户标记令牌用途的名称';
COMMENT ON COLUMN "auth_personal_access_tokens"."token_prefix" IS '仅用于识别令牌的公开前缀，不包含完整密钥';
COMMENT ON COLUMN "auth_personal_access_tokens"."secret_hash" IS '个人 API 令牌明文的 SHA-256 摘要';
COMMENT ON COLUMN "auth_personal_access_tokens"."scopes" IS '允许调用的精确权限代码列表，只能收窄用户 RBAC 权限';
COMMENT ON COLUMN "auth_personal_access_tokens"."expires_at" IS '个人 API 令牌失效时间';
COMMENT ON COLUMN "auth_personal_access_tokens"."revoked_at" IS '令牌撤销时间，为空表示未主动撤销';
COMMENT ON COLUMN "auth_personal_access_tokens"."last_used_at" IS '最近一次通过令牌完成认证的时间';
COMMENT ON COLUMN "auth_personal_access_tokens"."created_at" IS '令牌创建时间';
COMMENT ON COLUMN "auth_personal_access_tokens"."updated_at" IS '令牌最近更新时间';
COMMENT ON COLUMN "auth_personal_access_tokens"."deleted_at" IS '软删除时间戳，0 表示当前记录仍有效';
